import ast, pathlib
for f in ["tests/unit/orchestrator/test_session_status_from_job_results.py","tests/unit/orchestrator/test_config_system.py","tests/unit/orchestrator/test_first_sync_scope.py","tests/unit/cli/test_config_sync.py","tests/unit/test_sudoers.py"]:
    p=pathlib.Path(f); print(f"\n== {f}")
    t=ast.parse(p.read_text())
    def w(n):
        for x in n.body:
            if isinstance(x, ast.ClassDef): print("  #",x.name); w(x)
            elif isinstance(x,(ast.FunctionDef,ast.AsyncFunctionDef)) and x.name.startswith("test"):
                d=ast.get_docstring(x) or ""
                print("   -",x.name,":"," ".join(d.split())[:150])
    w(t)
EOF
